// Map the IMAP item to OpsPilot's RawEmail JSON. Attachments become base64 entries.
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const from = (j.from && j.from.value && j.from.value[0]) || {};
  const attachments = [];
  for (const [key, bin] of Object.entries(item.binary || {})) {
    attachments.push({ filename: bin.fileName || key, content_type: bin.mimeType || 'application/octet-stream', content_b64: bin.data });
  }
  out.push({ json: {
    message_id: j.messageId || null,
    from_name: from.name || null,
    from_email: from.address || 'unknown@unknown.invalid',
    to: (j.to && j.to.text) || 'ops@northwind-supply.de',
    subject: j.subject || '(no subject)',
    body: j.textPlain || j.text || '',
    received_at: j.date || new Date().toISOString(),
    attachments
  }});
}
return out;

